css.content:
/* Navigation menu on Radix: a thin bar; panels open in a bordered viewport below. */
.navmenu { position: relative; display: flex; }
.navmenu-list { display: flex; gap: var(--s1); margin: 0; padding: 0; list-style: none; }
.navmenu-link { display: inline-flex; align-items: center; padding: var(--s2) var(--s3); font-size: var(--text-sm); text-decoration: none; color: var(--muted); }
.navmenu-link:hover, .navmenu-link[data-state="open"] { color: var(--foreground); }
.navmenu-link[aria-current="page"], .navmenu-link[data-active] { color: var(--foreground); box-shadow: inset 0 -2px 0 var(--accent); }
.navmenu-link:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.navmenu-viewport-wrap { position: absolute; inset-inline-start: 0; top: 100%; z-index: var(--z-drawer); }
.navmenu-viewport { min-width: 14rem; background: var(--background); border: 1px solid var(--foreground); }
.navmenu-viewport[data-state="closed"] { display: none; }
.navmenu-content { padding: var(--s2); }
.navmenu-panel { display: grid; gap: var(--s1); }
.navmenu-content .navmenu-link { display: flex; }

